insert into public.question_bank (teks_code, teks_item_id, subject, grade_num, course, difficulty, qtype, prompt, choices, answer_idx, explanation, source, status, gen_batch)
select distinct on (v.prompt) v.code, i.id, d.subject,
       case when i.grade_level = 'K' then 0 when i.grade_level ~ '^[0-9]+' then substring(i.grade_level from '^[0-9]+')::smallint end,
       case when i.grade_level is null then i.grade_course_title end,
       v.diff, 'mc', v.prompt, v.choices, v.ans, v.expl, v.src, 'checked', 'hs_dance3_v1'
from (values
('117.308.c.1.A',3,'A dance student reviews video of a group piece and notes where the spacing between dancers shifted and her own balance wavered. She is analyzing what?','["Kinesthetic and spatial awareness", "Costume continuity", "Program layout", "Ticket sales"]'::jsonb,0,'She evaluates body sense and group spacing.','original'),
('117.308.c.1.A',3,'Which observation shows analysis of spatial awareness in a group?','["The music was loud", "The ensemble kept even distances while traveling in diagonal lines", "The costumes matched", "The lights were bright"]'::jsonb,1,'Spacing and pathways reflect spatial awareness.','original'),
('117.308.c.1.B',3,'A dancer who adds cross-training to build core strength and prevent overuse injuries is applying what?','["A ticketing plan", "A stage direction", "A comprehensive approach to health, safety and wellness", "A costume rule"]'::jsonb,2,'Cross-training supports dancer health.','original'),
('117.308.c.1.B',3,'Which choice best supports a dancer''s long-term wellness?','["Practicing through pain", "Sleeping four hours a night", "Skipping meals before shows", "Balanced nutrition, adequate sleep and rest days"]'::jsonb,3,'Recovery and nutrition protect dancers.','original'),
('117.308.c.1.C',3,'Comparing lyrical dance with hip-hop, a student notes that lyrical emphasizes fluid line while hip-hop emphasizes groove and isolations. She is doing what?','["Comparing the skills and styles of two genres", "Matching costumes", "Designing lights", "Rating music"]'::jsonb,0,'Comparison highlights genre differences.','original'),
('117.308.c.1.C',3,'Which vocabulary pair is correctly matched with a genre?','["Shuffle ball change and ballet", "Pas de bourree and ballet", "Floor roll and ballet barre only", "Grapevine and tap only"]'::jsonb,1,'Pas de bourree is a ballet step.','original'),
('117.308.c.1.D',3,'A student studies how the symmetry of a spider web could be translated into a group formation. She is doing what?','["Selling tickets", "Cutting music", "Differentiating designs found in natural environments", "Painting a set"]'::jsonb,2,'Natural designs can inform choreography.','original'),
('117.308.c.1.D',3,'Which source would offer a constructed-environment design to inspire a floor pattern?','["A flock of birds", "A mountain stream", "A rainstorm", "A city grid map"]'::jsonb,3,'A grid is a constructed pattern.','original'),
('117.308.c.2.A',3,'A student creates a short study that begins with a simple phrase and then alters its tempo, level and direction. This is an example of what?','["A dance study based on theme and variation", "A costume plan", "A warm-up", "A lighting cue"]'::jsonb,0,'Variations alter an original theme.','original'),
('117.308.c.2.A',3,'In a theme and variation, which change counts as a variation?','["Changing the floor color", "Performing the same phrase backwards or at a different size", "Changing the dancers'' names", "Changing the poster"]'::jsonb,1,'Variations modify the movement itself.','original'),
('117.308.c.2.B',3,'A dancer experiments with a movement by changing its weight, speed and focus before performing it. This is an example of what?','["Marking a spot", "Reading a score", "Experimenting during the creative process", "Counting seats"]'::jsonb,2,'Experimenting changes the movement''s qualities.','original'),
('117.308.c.2.B',3,'Why would a choreographer improvise before setting a phrase?','["To avoid practice", "To copy a video", "To stop creativity", "To discover new ideas that she might not plan"]'::jsonb,3,'Improvisation generates fresh material.','original'),
('117.308.c.2.C',3,'Two solos express grief. One uses slow collapsing falls and the other uses restrained, tense stillness. A student comparing them is examining what?','["How different movement choices express the same emotion", "Which costume is longer", "Which music is louder", "Which stage is bigger"]'::jsonb,0,'Different movement conveys one idea in different ways.','original'),
('117.308.c.2.C',3,'Contrasting emotions in a piece can be shown by changing which element?','["Seating", "Dynamics and tempo", "Ticket price", "Floor color only"]'::jsonb,1,'Dynamics and tempo express emotion.','original'),
('117.308.c.2.D',3,'A choreographer builds a phrase using intermediate elements such as cannon, call and response and contrast. What is she differentiating?','["Programs", "Costumes", "Compositional forms", "Sets"]'::jsonb,2,'Each form organizes movement differently.','original'),
('117.308.c.2.D',3,'In call and response, how do dancers interact?','["All dancers freeze", "Dancers leave the stage", "Dancers repeat the same word", "One dancer or group performs a phrase and another answers it"]'::jsonb,3,'Call and response is an interaction form.','original'),
('117.308.c.3.A',3,'A dancer performs and then evaluates a complex sequence for accuracy to the music. She is examining what?','["Rhythmic accuracy in a memorized complex sequence", "Costume fit", "Ticket sales", "Lighting levels"]'::jsonb,0,'Examination checks her rhythm.','original'),
('117.308.c.3.A',3,'What helps a dancer memorize a long, complex sequence?','["Ignoring the counts", "Breaking it into smaller phrases and practicing them in order", "Learning it once quickly", "Skipping repetition"]'::jsonb,1,'Chunking aids memory.','original'),
('117.308.c.3.B',3,'A dancer moves from a delicate, suspended gesture into a powerful, explosive leap. She is showing what?','["One flat quality", "Only stillness", "A wide range of dynamics", "No energy"]'::jsonb,2,'Dynamics are variations in force and quality.','original'),
('117.308.c.3.B',3,'Which pair of movement qualities shows contrast in dynamics?','["Quiet and quiet", "Slow and slow", "Smooth and smooth", "Sustained and percussive"]'::jsonb,3,'Sustained and percussive are contrasting.','original'),
('117.308.c.3.C',3,'A dancer performs a solo with her eyes focused outward and her energy reaching the back row. She is demonstrating what?','["Projection, confidence and expression", "A costume change", "Lack of preparation", "Hiding from the audience"]'::jsonb,0,'Projection engages the audience.','original'),
('117.308.c.3.C',3,'Which behavior best shows stage confidence during a performance?','["Stopping when a mistake occurs", "Committing fully to each movement and maintaining focus", "Looking down the whole time", "Rushing the counts"]'::jsonb,1,'Confidence includes commitment.','original'),
('117.308.c.3.D',3,'A teacher says an effective cool-down should include slow stretching and a gradual drop in heart rate. This helps the dancer do what?','["Increase injury risk", "Skip recovery", "Recover and reduce muscle soreness", "Raise the pulse"]'::jsonb,2,'Cool-downs support recovery.','original'),
('117.308.c.3.D',3,'Which element should an effective warm-up include to prepare for jumping?','["Eating a large meal", "Holding one static stretch for five minutes", "Sitting still", "Dynamic movements for the ankles, calves and quads"]'::jsonb,3,'Dynamic prep supports jumps.','original'),
('117.308.c.4.A',3,'A student compares the steps of Irish step dance and flamenco, noting differences in arm use and rhythm. What is she comparing?','["Steps, styles and traditions from various cultures", "Ticket policies", "Stage lights", "Costume prices"]'::jsonb,0,'Cultural dances vary in technique.','original'),
('117.308.c.4.A',3,'What tradition do many cultural dances preserve?','["Only competition", "Stories, ceremonies and community values", "Only fashion", "Only technology"]'::jsonb,1,'Cultural dances carry tradition.','original'),
('117.308.c.4.B',3,'A student evaluates how swing dances reflected the social changes of the 1930s and 1940s. She is evaluating dance in relation to what?','["A map scale", "A sports score", "A historical period and its social context", "A recipe"]'::jsonb,2,'Dance mirrors history.','original'),
('117.308.c.4.B',3,'Why did social dances such as the Charleston become popular in the 1920s?','["They were forbidden by law", "They were only for ballet", "They were unrelated to music", "They reflected a lively, changing culture after the war"]'::jsonb,3,'Dance reflects social energy.','original'),
('117.308.c.4.C',3,'A student choreographs a short dance for a school film project. This is an example of creating dance in what?','["Media and other content areas", "No setting", "A parking lot", "A math test"]'::jsonb,0,'Dance can be created for film.','original'),
('117.308.c.4.C',3,'Experimenting with dance in a science video might involve what?','["Painting a poster", "Showing the water cycle through movement", "Writing a recipe", "Measuring a stage"]'::jsonb,1,'Movement can express science concepts.','original'),
('117.308.c.4.D',3,'A student uses library databases and video archives to learn about a traditional dance''s origins. She is doing what?','["Skipping research", "Avoiding sources", "Researching historical and cultural dance forms using technology", "Guessing"]'::jsonb,2,'Technology supports dance research.','original'),
('117.308.c.4.D',3,'Which source would give reliable information on the history of a folk dance?','["An unsigned post", "A random comment", "A rumor", "A museum site or a scholarly dance history book"]'::jsonb,3,'Credible sources are best.','original'),
('117.308.c.5.A',3,'A student compares the characteristics of ballet and modern dance, noting turnout versus parallel positions. What is she doing?','["Comparing characteristics and qualities of dances", "Counting costumes", "Choosing seats", "Ordering tickets"]'::jsonb,0,'Comparison identifies distinguishing features.','original'),
('117.308.c.5.A',3,'Which quality would most likely be described as weighted and grounded?','["Aerial lifts only", "Modern dance", "Pointe work", "Tap rhythms only"]'::jsonb,1,'Modern dance often uses weight.','original'),
('117.308.c.5.B',3,'A student reviews a concert from the viewpoint of a critic, then of a choreographer. She is analyzing dance from what?','["A guess", "A single view", "Different perspectives", "No view"]'::jsonb,2,'Each role notices different details.','original'),
('117.308.c.5.B',3,'A dance critic writes about a piece''s use of space, energy and meaning. Which part of the job is this?','["Selling tickets", "Moving sets", "Sewing costumes", "Analyzing and evaluating a performance"]'::jsonb,3,'Critics analyze and evaluate.','original'),
('117.308.c.5.C',3,'A dancer applies her understanding of physics when planning how to turn with more speed. This shows the relationship between dance and what?','["Another content area, science", "A vote", "A sport score", "A recipe"]'::jsonb,0,'Physics explains rotation.','original'),
('117.308.c.5.C',3,'Which skill from dance transfers to teamwork in other classes?','["Working alone only", "Collaboration, listening and responsibility", "Avoiding feedback", "Hiding mistakes"]'::jsonb,1,'Dance builds teamwork.','original'),
('117.308.c.5.D',3,'A student documents her choreography progress with clips, notes and photos in an online collection. This is called what?','["A costume rack", "A ticket stub", "A dance portfolio", "A lighting plot"]'::jsonb,2,'A portfolio shows growth.','original'),
('117.308.c.5.D',3,'What is one benefit of keeping a digital dance portfolio?','["It prevents feedback", "It limits creativity", "It deletes the performance", "It tracks growth and can be shared with others"]'::jsonb,3,'Portfolios track and share growth.','original')
) as v(code, diff, prompt, choices, ans, expl, src)
join public.teks_items i on i.code = v.code and i.is_standard
join public.teks_documents d on d.id = i.document_id and d.subject = 'Fine Arts' and d.language = 'en'
on conflict (fingerprint) do nothing;
